<button type="button" data-theme-toggle class="theme-toggle inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-xl border border-gray-200 bg-white/75 text-gray-700 shadow-sm backdrop-blur transition hover:border-amber-300 hover:bg-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-amber-500" aria-label="Switch to dark mode" title="Switch to dark mode">
    <x-icon name="moon" class="h-[18px] w-[18px]" data-theme-icon="moon" />
    <x-icon name="sun" class="hidden h-[18px] w-[18px]" data-theme-icon="sun" />
</button>
